{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if "nodes" not in case:
        raise ValueError("Missing 'nodes' field")
    if "required_symbols" not in case:
        raise ValueError("Missing 'required_symbols' field")

    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])

    # Validate nodes
    node_ids = set()
    for node in nodes:
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError(f"Node missing field: {field}")
        if node["id"] in node_ids:
            raise ValueError(f"Duplicate node id: {node['id']}")
        node_ids.add(node["id"])

    # Validate parents exist
    for node in nodes:
        if node["parent"] is not None and node["parent"] not in node_ids:
            raise ValueError(f"Parent not found: {node['parent']}")

    # Verify required symbols are initially represented
    initial_symbols = {n["symbol"] for n in nodes}
    for sym in required_symbols:
        if sym not in initial_symbols:
            raise ValueError(f"Required symbol not present in tree: {sym}")

    # Build children map (stable list order from input)
    children = {node["id"]: [] for node in nodes}
    for node in nodes:
        if node["parent"] is not None:
            children[node["parent"]].append(node["id"])

    # id -> node map for symbol lookups
    id_to_node = {node["id"]: node for node in nodes}

    # Process order: deeper nodes first; stable tie-break by node ID (lexicographic)
    sorted_nodes = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    retained = set(node_ids)
    removed_order = []

    for node in sorted_nodes:
        nid = node["id"]

        # Skip non-removable nodes
        if not node["removable"]:
            continue

        # Skip nodes that still have retained children
        if any(child in retained for child in children[nid]):
            continue

        # Tentatively remove
        retained.discard(nid)

        # Check all required symbols are still represented in the retained set
        retained_symbols = {id_to_node[rid]["symbol"] for rid in retained}
        if required_symbols.issubset(retained_symbols):
            # Removal is valid; record it
            removed_order.append(nid)
        else:
            # Restore: removal would violate required-symbol coverage
            retained.add(nid)

    retained_sorted = sorted(retained)

    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": retained_sorted
    }
